def synthetic_full_cpu_run(bind, bind_json, label, policy, scope, commit, collected_rows,
                           executed_rows=None, mutate_collection=None, mutate_execution=None,
                           source_identity=None, review_sha='6' * 64):
    """UNEXECUTED in-memory fixtures; no original CPU history or static total claim."""
    executed_rows = list(collected_rows if executed_rows is None else executed_rows)
    prefix = [policy['interpreter']['argv0'], '-m', 'pytest']
    options = ['-q', '--disable-warnings', '-p', 'no:cacheprovider', '-c', '/dev/null', '--noconftest',
               '--rootdir', policy['cwd'], '--basetemp']
    collection_command = prefix + ['--collect-only'] + options + [policy['collection_basetemp']] + policy['test_files']
    execution_command = prefix + options + [policy['run_basetemp'], '--junitxml', policy['junit_path']] + policy['test_files']
    snapshot_field = ('controls_manifest_sha256' if scope == 'FRESH200_DEPLOYMENT_CONTROLS_CPU_ONLY' else
                      'runtime_snapshot_sha256' if scope == 'FRESH200_RUNTIME_CPU_REGRESSIONS' else 'source_snapshot_sha256')
    common = copy.deepcopy(dict(code_commit=commit, scope=scope, node='h100-8', cwd=policy['cwd'], interpreter=policy['interpreter'],
        test_files=policy['test_files'], test_file_records=policy['test_file_records'],
        execution_environment=policy['execution_environment'], config_policy='EMPTY_DEV_NULL', rootdir=policy['cwd'],
        environment_sanitization=dict(strategy='EXACT_ALLOWLIST_NO_INHERITANCE', inherited_environment_forwarded=False,
            cleared_inputs=dict(PYTEST_ADDOPTS='empty', PYTEST_PLUGINS='absent'), removed_input_names=['PYTEST_DEBUG']),
        actual_gpu_acceptance=False, production_READY=False, formal_iterations=0, review_sha256=review_sha))
    common[snapshot_field] = policy['snapshot_sha256']
    if scope == 'FRESH200_DEPLOYMENT_CONTROLS_CPU_ONLY':
        common.update(controls_files_digest=policy['input_files_digest'], source_or_runtime_imported=False,
                      actual_slurm_submitted=False, actual_execution=True, management_helper=policy['management_helper'],
                      input_file_records=policy['input_file_records'], input_files_digest=policy['input_files_digest'],
                      controls_directory_names_before=sorted(contract.NAMES))
    if policy.get('role') in ('source', 'runtime'):
        common.update(actual_execution=True, management_helper=policy['management_helper'],
            input_file_records=policy['input_file_records'], input_files_digest=policy['input_files_digest'],
            source_snapshot_sha256=policy['source_snapshot_sha256'])
    started_common = copy.deepcopy(common)
    started_collection_command = copy.deepcopy(collection_command)
    started_execution_command = copy.deepcopy(execution_command)
    nodes = [row[0] for row in collected_rows]
    collected_ids = [row[1] + '::' + row[2] for row in collected_rows]
    collection_log = bind('/proofs/' + label + '-collection.log',
        ('\n'.join(nodes) + '\n\n' + str(len(nodes)) + ' tests collected in 0.01s\n').encode())
    collection = dict(common, command=collection_command, exit_code=0, collection_log=collection_log['path'],
        log_record=collection_log, log_sha256=collection_log['sha256'], node_ids=nodes,
        canonical_case_ids=collected_ids, collected=len(nodes))
    if mutate_collection:
        mutate_collection(collection)
    collection_record = bind_json('/proofs/' + label + '-COLLECTION-RESULT.json', collection)
    counts = dict(collected=len(executed_rows), passed=0, failed=0, errors=0, skipped=0)
    cases = []; failure_ids = []
    for _, classname, name, outcome in executed_rows:
        counts[outcome] += 1
        marker = {'passed': '', 'failed': '<failure/>', 'errors': '<error/>', 'skipped': '<skipped/>'}[outcome]
        cases.append('<testcase classname="' + classname + '" name="' + name + '">' + marker + '</testcase>')
        if outcome in ('failed', 'errors'):
            failure_ids.append(classname + '::' + name)
    xml = ('<testsuites><testsuite hostname="h100-8" tests="' + str(counts['collected']) + '" failures="' + str(counts['failed'])
           + '" errors="' + str(counts['errors']) + '" skipped="' + str(counts['skipped']) + '">'
           + ''.join(cases) + '</testsuite></testsuites>').encode()
    junit = bind(policy['junit_path'], xml)
    log = bind('/proofs/' + label + '-pytest.log', b'Synthetic raw CPU fixture output, not actual execution\n')
    actual = dict(common, command=execution_command, executed_command=execution_command, actual_cases=counts,
        collection_record=collection_record, collection_log_record=collection_log, log=log['path'], log_record=log,
        log_sha256=log['sha256'], junit=junit['path'], junit_record=junit, junit_sha256=junit['sha256'],
        exit_code=int(bool(counts['failed'] + counts['errors'])), collected_canonical_case_ids=collected_ids,
        executed_canonical_case_ids=sorted(row[1] + '::' + row[2] for row in executed_rows))
    if source_identity:
        actual['source_after'] = source_identity
        if policy.get('role') in ('source', 'runtime'):
            actual['source_before'] = source_identity
    if scope == 'FRESH200_DEPLOYMENT_CONTROLS_CPU_ONLY':
        actual.update(input_file_records_after=policy['input_file_records'], input_files_digest_after=policy['input_files_digest'],
                      controls_directory_names_after=sorted(contract.NAMES))
    if mutate_execution:
        mutate_execution(actual)
    result = bind_json('/proofs/' + label + '-RESULT.json', actual)
    run = dict(record=result, log_record=log, junit_record=junit, collection_record=collection_record,
        collection_log_record=collection_log, execution_scope=scope, executed_command=actual['command'],
        test_files=actual['test_files'], exit_code=actual['exit_code'], failure_ids=sorted(failure_ids), **counts)
    records = [result, log, junit, collection_record, collection_log]
    if source_identity or scope == 'FRESH200_DEPLOYMENT_CONTROLS_CPU_ONLY':
        started = dict(started_common, command=started_execution_command, collection_command=started_collection_command)
        if source_identity:
            started['source_before'] = source_identity
        else:
            started.update(input_file_records_before=policy['input_file_records'], input_files_digest_before=policy['input_files_digest'])
        run['started_record'] = bind_json('/proofs/' + label + '-STARTED.json', started)
        records.append(run['started_record'])
    return run, records


def test_frozen_ff7_observation_cannot_become_final_candidate():
    with pytest.raises(ValueError, match='Historical/pending candidate'):
        contract.validate_candidate(dict(status='CANDIDATE_NOT_READY_FINAL_RUNTIME_DEPENDENCY_PENDING'))


def test_bound_original_rejects_same_length_different_bytes(tmp_path):
    path = tmp_path / 'original.json'; path.write_text('{"value":1}')
    item = contract.record(path); path.write_text('{"value":2}')
    with pytest.raises(ValueError, match='Changed bound bytes'):
        contract.read_bound(item)


def test_verified_json_is_parsed_without_reopening_path(tmp_path, monkeypatch):
    path = tmp_path / 'one-buffer.json'; path.write_bytes(b'{"value":1}')
    item = contract.record(path)
    def forbidden_reopen(*args, **kwargs):
        raise AssertionError('JSON parsing must use the verified open-descriptor buffer')
    monkeypatch.setattr(Path, 'read_bytes', forbidden_reopen)
    assert contract.read_bound(item) == dict(value=1)


def test_replacement_during_bound_read_is_rejected(tmp_path, monkeypatch):
    path = tmp_path / 'review.json'; path.write_bytes(b'{"value":1}')
    item = contract.record(path); replacement = tmp_path / 'replacement.json'; replacement.write_bytes(b'{"value":2}')
    original = contract.os.read; replaced = []
    def replace_after_read(descriptor, size):
        block = original(descriptor, size)
        if block and not replaced:
            replacement.replace(path); replaced.append(True)
        return block
    monkeypatch.setattr(contract.os, 'read', replace_after_read)
    with pytest.raises(ValueError, match='identity changed during read'):
        contract.read_bound(item)
    assert replaced


def test_duplicate_review_json_key_is_rejected(tmp_path):
    path = tmp_path / 'duplicate.json'; path.write_bytes(b'{"status":"FAIL","status":"PASS"}')
    with pytest.raises(ValueError, match='Duplicate JSON key'):
        contract.read_bound(contract.record(path))


def test_symlink_bound_proof_cannot_alias_a_review(tmp_path):
    path = tmp_path / 'original.json'; path.write_bytes(b'{}')
    link = tmp_path / 'alias.json'; link.symlink_to(path)
    with pytest.raises(ValueError, match='Noncanonical proof'):
        contract.read_bound(contract.record(link))


def test_exclusive_output_preserves_first_intent(tmp_path):
    path = tmp_path / 'intent.json'
    contract.write_once(path, dict(status='CLAIMED_NO_RESUBMISSION'))
    first = path.read_bytes()
    with pytest.raises(FileExistsError):
        contract.write_once(path, dict(status='replacement'))
    assert path.read_bytes() == first


