# All following fixtures are UNEXECUTED synthetic raw bytes, never observed history.
def controls_full_fixture(executed_rows=None, collection_rows=None, mutate_collection=None, mutate_execution=None):
    fixture = 'test_deployment_controls_v7.py'; classname = 'test_deployment_controls_v7'
    rows = [
        (fixture + '::test_plain', classname, 'test_plain', 'passed'),
        (fixture + '::test_parameterized[SBATCH_ARRAY_INX-0-1]', classname, 'test_parameterized[SBATCH_ARRAY_INX-0-1]', 'passed'),
        (fixture + '::TestScope::test_parameterized[SBATCH_CLUSTERS-foreign]', classname + '.TestScope',
         'test_parameterized[SBATCH_CLUSTERS-foreign]', 'passed'),
        (fixture + '::test_parameterized[param::nested[bracket]]', classname,
         'test_parameterized[param::nested[bracket]]', 'passed')]
    control_files = [dict(path=str(contract.CONTROLS / name), bytes=19, sha256=hashlib.sha256(name.encode()).hexdigest())
                     for name in contract.NAMES]
    policy = dict(schema='EXACT_FULL_PYTEST_INVOCATION_V1', cwd=str(contract.CONTROLS),
        interpreter=dict(path='/fixture/python3.10', argv0='/fixture/env/bin/python', resolved_path='/fixture/python3.10',
                         bytes=19, sha256='e' * 64),
        test_files=[fixture], test_file_records=[row for row in control_files if Path(row['path']).name == fixture],
        input_file_records=control_files, input_files_digest=contract.records_digest(control_files), snapshot_sha256='a' * 64,
        config_policy='EMPTY_DEV_NULL', plugin_policy='BUILTIN_ONLY_AUTOLOAD_DISABLED_NO_CONFTEST',
        execution_environment=dict(PATH='/usr/bin:/bin', CUDA_VISIBLE_DEVICES='', PYTEST_ADDOPTS='',
            PYTEST_DISABLE_PLUGIN_AUTOLOAD='1', PYTHONDONTWRITEBYTECODE='1', PYTHONNOUSERSITE='1'),
        collection_basetemp='/proofs/controls-collect-tmp', run_basetemp='/proofs/controls-pytest-tmp', junit_path='/proofs/controls.xml')
    buffers = {}
    def bind(path, raw):
        buffers[path] = raw
        return dict(path=path, bytes=len(raw), sha256=hashlib.sha256(raw).hexdigest())
    def bind_json(path, value):
        return bind(path, json.dumps(value, sort_keys=True).encode())
    management = bind(str(contract.ROOT / 'tools/management/controls-cpu-once-v7.py'),
                      b'UNEXECUTED synthetic management helper identity only\n')
    policy.update(role='controls', execution_scope='FRESH200_DEPLOYMENT_CONTROLS_CPU_ONLY',
        management_helper=management, single_execution_only=True, GPU_allowed=False, READY_allowed=False,
        Slurm_submission_allowed=False, formal_iterations_contributed=0)
    policy['collection_command'], policy['executed_command'] = contract.approved_cpu_commands(policy)
    run, originals = synthetic_full_cpu_run(bind, bind_json, 'controls', policy, 'FRESH200_DEPLOYMENT_CONTROLS_CPU_ONLY', None,
        rows if collection_rows is None else collection_rows, rows if executed_rows is None else executed_rows,
        mutate_collection, mutate_execution)
    originals.append(management)
    receipt = dict(status='PASS', scope='FRESH200_DEPLOYMENT_CONTROLS_CPU_ONLY', actual_execution=True, gpu_used=False,
        actual_slurm_submitted=False, source_or_runtime_imported=False, exit_code=run['exit_code'],
        manifest_sha256='a' * 64, controls_files_digest=policy['input_files_digest'],
        current_run=run, raw_execution_records=originals,
        executed_case_ids=sorted(row[1] + '::' + row[2] for row in (rows if executed_rows is None else executed_rows)),
        **{key: run[key] for key in ('collected', 'passed', 'failed', 'errors', 'skipped')})
    candidate = dict(control_files=control_files, proofs=dict(controls_manifest=dict(sha256='a' * 64),
        controls_review=dict(sha256='6' * 64)))
    review = dict(approved_cpu_policy=policy)
    manifest = dict(static_checks=dict(test_functions_unexecuted=['test_plain', 'test_parameterized']),
        management_helper=management, cpu_required_test_files=[fixture])
    def read_bytes(item):
        raw = buffers[item['path']]
        assert len(raw) == item['bytes'] and hashlib.sha256(raw).hexdigest() == item['sha256']
        return raw
    def read(item):
        return json.loads(read_bytes(item))
    return receipt, review, manifest, candidate, contract.closure(originals, 'fixture originals'), read, read_bytes, rows


