def original_v8_dictionary_review_fixture():
    # Original v8 layout, using synthetic three-file contents rather than fake490 facts.
    candidate, proofs = strict_static_fixture(); source = proofs['source_review']; manifest = proofs['source_manifest']
    candidate.update(source_version=8, source_review_schema='gigpo-e1-fresh200-v8-preexec-review')
    source.update(schema=candidate['source_review_schema'], reviewer=dict(root_conversation_inherited=False, independent_after_v8_freeze=True))
    manifest['schema'] = 'fresh200-source-static-v8'
    rows = manifest['full_tracked_source_files']; changed = copy.deepcopy(rows[:2]); unchanged = [dict(rows[2], same_as_base=True)]
    manifest.update(files=changed, unchanged_files=unchanged)
    source.update(file_receipts=copy.deepcopy(changed), unchanged_files_receipts=copy.deepcopy(unchanged),
        freeze=dict(snapshot_path='/proofs/source-v8.json', snapshot_sha256='1' * 64, independently_hash_matched=True,
            source_clean=True, actual_new_code_commit=candidate['source_commit'], full_tracked_records_exactly_matched=True,
            full_tracked_file_count=3, actual_source_tracked_files_digest=manifest['source_tracked_files_digest']))
    return candidate, proofs


def test_original_v8_dictionary_freeze_and_two_receipt_lists_are_consumed():
    candidate, proofs = original_v8_dictionary_review_fixture(); contract.validate_static_reviews(candidate, proofs)


@pytest.mark.parametrize('change', ['freeze_sha', 'freeze_digest', 'changed_missing', 'unchanged_missing', 'unchanged_tamper'])
def test_original_v8_dictionary_freeze_and_receipt_tampering_is_rejected(change):
    candidate, proofs = original_v8_dictionary_review_fixture(); source = proofs['source_review']
    if change == 'freeze_sha':
        source['freeze']['snapshot_sha256'] = 'f' * 64
    elif change == 'freeze_digest':
        source['freeze']['actual_source_tracked_files_digest'] = 'f' * 64
    elif change == 'changed_missing':
        source['file_receipts'].pop()
    elif change == 'unchanged_missing':
        source['unchanged_files_receipts'].clear()
    else:
        source['unchanged_files_receipts'][0]['sha256'] = 'f' * 64
    with pytest.raises(ValueError, match='dictionary freeze/full source closure|changed/unchanged receipts|Missing full tracked source inventory'):
        contract.validate_static_reviews(candidate, proofs)


