def original_runtime8_literal_pass_fixture():
    fixture = json.loads(_ORIGINAL_RUNTIME8_COMPATIBILITY_FIXTURE_JSON)
    return fixture['candidate'], fixture['proofs']


def test_original_runtime8_literal_pass_consumes_full39_source490_original_shape():
    candidate, proofs = original_runtime8_literal_pass_fixture()
    assert proofs['runtime_review']['schema'] == 1 and type(proofs['runtime_review']['schema']) is int
    assert proofs['runtime_review']['status'] == 'PASS'
    assert len(candidate['runtime_files']) == 39 and len(candidate['source_files']) == 490
    contract.validate_static_reviews(candidate, proofs)


@pytest.mark.parametrize('status', ['FAIL', 'PASS ', 'PASS_FAKE', False, None])
def test_original_runtime8_literal_pass_rejects_false_or_unaccepted_status(status):
    candidate, proofs = original_runtime8_literal_pass_fixture(); proofs['runtime_review']['status'] = status
    with pytest.raises(ValueError, match='Failed/non-static original runtime review'):
        contract.validate_static_reviews(candidate, proofs)


@pytest.mark.parametrize('change', ['runtime_bool', 'candidate_bool', 'both_bool', 'string_schema'])
def test_original_runtime_schema_one_rejects_bool_and_other_types(change):
    candidate, proofs = original_runtime8_literal_pass_fixture()
    if change in ('runtime_bool', 'both_bool'):
        proofs['runtime_review']['schema'] = True
    if change in ('candidate_bool', 'both_bool'):
        candidate['runtime_review_schema'] = True
    if change == 'string_schema':
        candidate['runtime_review_schema'] = proofs['runtime_review']['schema'] = '1'
    with pytest.raises(ValueError, match='Failed/non-static original runtime review'):
        contract.validate_static_reviews(candidate, proofs)


@pytest.mark.parametrize('change', ['scope', 'borrow_v8_for_v9', 'report_version', 'missing_independence',
    'inherited_context', 'prior_PASS_substitute', 'no_postfreeze', 'CPU_report_substitute'])
def test_original_runtime_literal_pass_requires_own_version_scope_and_independence(change):
    candidate, proofs = original_runtime8_literal_pass_fixture(); runtime = proofs['runtime_review']
    if change == 'scope':
        runtime['scope'] = contract.SCOPE
    elif change == 'borrow_v8_for_v9':
        candidate['runtime_version'] = 9
        runtime['scope'] = 'INDEPENDENT_FROZEN_FRESH200_CALIBRATION_V9_STATIC_PREEXEC_REVIEW_ONLY'
    elif change == 'report_version':
        runtime['runtime_version'] = 9
    elif change == 'missing_independence':
        runtime['independence'].pop('independent_post_freeze_review')
    elif change == 'inherited_context':
        runtime['independence']['root_conversation_inherited'] = True
    elif change == 'prior_PASS_substitute':
        runtime['independence']['prior_source_or_runtime_PASS_used_as_substitute'] = True
    elif change == 'no_postfreeze':
        runtime['independence']['independent_post_freeze_review'] = False
    else:
        runtime['independence']['completed_source_CPU_report_used_as_runtime_acceptance'] = True
    with pytest.raises(ValueError, match='standalone runtime review scope|mismatched version/findings|post-freeze independence|not independent after freeze|typed runtime9/10/11/12 report version/status/scope'):
        contract.validate_static_reviews(candidate, proofs)


