@pytest.mark.parametrize('change', ['findings', 'blockers', 'CPU_denied', 'two_CPU_decisions', 'gpu_top', 'ready_top',
    'formal_top', 'formal_bool'])
def test_literal_pass_requires_zero_blockers_one_CPU_decision_and_false_acceptance(change):
    candidate, proofs = original_runtime8_literal_pass_fixture(); runtime = proofs['runtime_review']
