@pytest.mark.parametrize('change', ['manifest_sha', 'manifest_hash', 'runtime_missing', 'runtime_sha', 'runtime_count',
    'source_sha', 'source_missing', 'source_record_sha', 'source_count', 'source_dirty', 'source_digest'])
def test_literal_pass_original_manifest_and_full_runtime_source_closures_are_exact(change):
    candidate, proofs = original_runtime8_literal_pass_fixture(); frozen = proofs['runtime_review']['frozen_inputs']
    if change == 'manifest_sha':
        frozen['manifest']['sha256'] = 'f' * 64
    elif change == 'manifest_hash':
        frozen['manifest']['actual_hash_match'] = False
    elif change == 'runtime_missing':
        frozen['runtime']['file_receipts'].pop()
    elif change == 'runtime_sha':
        frozen['runtime']['file_receipts'][0]['sha256'] = 'f' * 64
    elif change == 'runtime_count':
        frozen['runtime']['actual_file_count'] -= 1
    elif change == 'source_sha':
        frozen['source_snapshot']['sha256'] = 'f' * 64
    elif change == 'source_missing':
        frozen['source_snapshot']['full490_records'].pop()
    elif change == 'source_record_sha':
        frozen['source_snapshot']['full490_records'][0]['sha256'] = 'f' * 64
    elif change == 'source_count':
        frozen['source_snapshot']['actual_source_hash_matches'] -= 1
    elif change == 'source_dirty':
        frozen['source_snapshot']['source_clean_verified'] = False
    else:
        frozen['source_snapshot']['actual_full_source_digest'] = 'f' * 64
    with pytest.raises(ValueError, match='manifest/source snapshot differs|full runtime closure differs|full source closure differs|Covered source changed'):
        contract.validate_static_reviews(candidate, proofs)


# Exact original failed-runtime8 record shape below is immutable fixture material.
# The positive fixture is explicitly synthesized and UNEXECUTED; it is not an observed v9 run.
def original_runtime_cpu_format_fixture(successful_synthetic=False, edit_inputs=None):
    """Full original 529-input/158-ID shape; success is UNEXECUTED synthesis only."""
    material = json.loads(_ORIGINAL_FAILED_RUNTIME8_CPU_FIXTURE_JSON)
    documents = material['documents']; started = documents['STARTED.json']
    collected = documents['COLLECTION-RESULT.json']; actual = documents['RESULT.json']
    source_repo = next(str(Path(row['path']).parent) for row in actual['input_file_records']
                       if Path(row['path']).name == '.gitignore')
    original_helpers = actual['cwd']; helpers = original_helpers
    inputs = copy.deepcopy(actual['input_file_records'])
    runtime_manifest = actual['runtime_snapshot_sha256']; review_sha = actual['review_sha256']
    if successful_synthetic:
        # This future-path structural counterexample changes neither original records nor history.
        helpers = str(contract.ROOT / 'tools/fresh200-calibration-v9')
        runtime_manifest = material['runtime9_frozen_fixture_input']['record']['sha256']
        review_sha = 'f' * 64  # Explicit synthetic review identity, not an existing PASS report.
        inputs = [row for row in inputs if row['path'].startswith(source_repo + '/')]
        inputs += [dict(path=helpers + '/' + row['relative_path'], bytes=row['bytes'], sha256=row['sha256'])
                   for row in material['runtime9_frozen_fixture_input']['files']]
    source_files = [row for row in inputs if row['path'].startswith(source_repo + '/')]
    runtime_files = [row for row in inputs if row['path'].startswith(helpers + '/')]
    test_records = [dict(relative_path=name, **{key: next(row[key] for row in runtime_files
                    if row['path'] == helpers + '/' + name) for key in ('bytes', 'sha256')})
                    for name in actual['test_files']]
    policy = dict(schema='EXACT_FULL_PYTEST_INVOCATION_V1', cwd=helpers,
        interpreter=copy.deepcopy(actual['interpreter']), test_files=actual['test_files'], test_file_records=test_records,
        input_file_records=inputs, input_files_digest=contract.records_digest(inputs), snapshot_sha256=runtime_manifest,
        execution_environment=copy.deepcopy(actual['execution_environment']), config_policy=actual['config_policy'],
        plugin_policy=actual['plugin_policy'], dependency_receipt=actual['dependency_receipt'],
        collection_basetemp='/proofs/UNEXECUTED-runtime-collect-tmp' if successful_synthetic else
            started['collection_command'][started['collection_command'].index('--basetemp') + 1],
        run_basetemp='/proofs/UNEXECUTED-runtime-pytest-tmp' if successful_synthetic else
            started['command'][started['command'].index('--basetemp') + 1],
        junit_path='/proofs/UNEXECUTED-runtime.xml' if successful_synthetic else actual['junit'])
    if edit_inputs:
        edit_inputs(policy['input_file_records'])
        policy['input_files_digest'] = contract.records_digest(policy['input_file_records'])
    collection_command, command = contract.approved_cpu_commands(policy)
    buffers = {}
    def bind(path, raw):
        buffers[path] = raw
        return dict(path=path, bytes=len(raw), sha256=hashlib.sha256(raw).hexdigest())
    def bind_json(path, value):
        return bind(path, json.dumps(value, sort_keys=True).encode())
    label = 'UNEXECUTED-full-runtime-shape' if successful_synthetic else 'original-failed-runtime8-shape'
    if successful_synthetic:
        identity = dict(commit=actual['code_commit'], clean=True, source_files=len(source_files),
            source_digest=contract.relative_source_digest([dict(relative_path=Path(row['path']).relative_to(source_repo).as_posix(),
                bytes=row['bytes'], sha256=row['sha256']) for row in source_files]),
            runtime_files=len(runtime_files), runtime_manifest_sha256=runtime_manifest)
        for document in (started, collected, actual):
            document.update(cwd=helpers, rootdir=helpers, test_file_records=test_records,
                input_file_records=policy['input_file_records'], input_files_digest=policy['input_files_digest'],
                runtime_snapshot_sha256=runtime_manifest, review_sha256=review_sha)
            document['execution_environment']['PYTHONPATH'] = ':'.join(
                helpers if part == original_helpers else part
                for part in document['execution_environment']['PYTHONPATH'].split(':'))
        # Preserve the same exact constant environment in policy, STARTED, collection, and RESULT.
        policy['execution_environment'] = copy.deepcopy(actual['execution_environment'])
        started.update(command=command, collection_command=collection_command, source_before=identity)
        collected.update(command=collection_command)
        actual.update(command=command, executed_command=command, source_after=identity,
            exit_code=0, passed=actual['collected'], failed=0, errors=0, skipped=0, failure_ids=[],
            status='UNEXECUTED_SYNTHETIC_SUCCESS_FORMAT_ONLY', actual_cases=dict(collected=actual['collected'],
                passed=actual['collected'], failed=0, errors=0, skipped=0))
        import xml.etree.ElementTree as ET
        tree = ET.fromstring(material['raw_text']['junit.xml'])
        for case in tree.iter('testcase'):
            for child in list(case):
                if child.tag in ('failure', 'error', 'skipped'):
                    case.remove(child)
        for suite in tree.iter('testsuite'):
            suite.set('failures', '0'); suite.set('errors', '0'); suite.set('skipped', '0')
        junit_raw = ET.tostring(tree)
        log_raw = b'UNEXECUTED synthesized successful original-record format fixture; no observed execution\n'
    else:
        junit_raw = material['raw_text']['junit.xml'].encode(); log_raw = material['raw_text']['pytest.log'].encode()
    collection_log = bind(collected['collection_log'], material['raw_text']['collection.log'].encode())
    collection_record = bind_json('/proofs/' + label + '-COLLECTION-RESULT.json', collected)
    log = bind(actual['log'], log_raw); junit = bind(policy['junit_path'], junit_raw)
    actual.update(collection_record=collection_record, collection_result_record=collection_record,
        collection_log_record=collection_log, log_record=log, log_sha256=log['sha256'], junit=junit['path'],
        junit_record=junit, junit_sha256=junit['sha256'])
    result = bind_json('/proofs/' + label + '-RESULT.json', actual)
    start_record = bind_json('/proofs/' + label + '-STARTED.json', started)
    run = dict(record=result, log_record=log, junit_record=junit, collection_record=collection_record,
        collection_log_record=collection_log, started_record=start_record, execution_scope=actual['scope'],
        executed_command=command, test_files=actual['test_files'], exit_code=actual['exit_code'], failure_ids=actual['failure_ids'],
        **actual['actual_cases'])
    originals = [start_record, collection_record, collection_log, result, log, junit]
    candidate = dict(repo=source_repo, helpers=helpers, source_commit=actual['code_commit'],
        source_files=source_files, runtime_files=runtime_files, proofs=dict(
            source_manifest=dict(sha256=actual['source_snapshot_sha256']), runtime_manifest=dict(sha256=runtime_manifest),
            runtime_review=dict(sha256=review_sha), runtime_cpu=dict(sha256='e' * 64)))
    receipt = dict(status='PASS' if successful_synthetic else 'FAILED_CPU_OR_COVERAGE', scope=actual['scope'],
        actual_execution=True, gpu_used=False, source_commit=actual['code_commit'], manifest_sha256=runtime_manifest,
        exit_code=actual['exit_code'], runtime_files_digest=contract.records_digest(runtime_files),
        current_run=run, raw_execution_records=originals, **actual['actual_cases'])
    review = dict(status='PASS', scope='FRESH200_RUNTIME_CPU_EVIDENCE_ONLY', source_commit=actual['code_commit'],
        manifest_sha256=runtime_manifest, cpu_receipt_sha256='e' * 64, independent_review=True,
        complete_required_cpu_coverage_accepted=True, approved_current_invocation=policy)
    def read_bytes(item):
        raw = buffers[item['path']]
        assert len(raw) == item['bytes'] and hashlib.sha256(raw).hexdigest() == item['sha256']
        return raw
    def read(item):
        return json.loads(read_bytes(item))
    return receipt, review, candidate, contract.closure(originals, 'full original-shape fixture'), read, read_bytes


