    assert receipt['failed'] == 1 and receipt['passed'] == 157
    assert len(review['approved_current_invocation']['input_file_records']) == 529
    with pytest.raises(ValueError, match='skips/fails/errors'):
        contract.validate_full_cpu_run(receipt['current_run'], candidate['source_commit'],
            ('FRESH200_RUNTIME_CPU_REGRESSIONS',), evidence, review['approved_current_invocation'], read, read_bytes)
    with pytest.raises(ValueError, match='Actual successful CPU evidence missing'):
        contract.validate_cpu(receipt, review, 'runtime', candidate, evidence, read, read_bytes)


