@pytest.mark.parametrize('change', ['source_snapshot', 'runtime_snapshot', 'review_sha', 'input_records', 'input_digest',
    'before_identity', 'after_identity', 'started_environment', 'top_passed', 'top_failed', 'top_failure_ids'])
def test_runtime_actual_format_rejects_original_binding_identity_or_count_tamper(change):
    receipt, review, candidate, evidence, read, read_bytes = original_runtime_cpu_format_fixture(True)
    def tampered(item):
        original = read(item)
        if item == receipt['current_run']['started_record']:
            field = {'source_snapshot': 'source_snapshot_sha256', 'runtime_snapshot': 'runtime_snapshot_sha256',
                'review_sha': 'review_sha256', 'input_records': 'input_file_records', 'input_digest': 'input_files_digest'}.get(change)
            if field:
                original[field] = [] if field == 'input_file_records' else '0' * 64
            if change == 'before_identity':
                original['source_before']['clean'] = False
            if change == 'started_environment':
                original['execution_environment']['PYTEST_ADDOPTS'] = '-k subset'
        if item == receipt['current_run']['record']:
            if change == 'after_identity':
                original['source_after']['source_files'] -= 1
            if change == 'top_passed':
                original['passed'] -= 1
            if change == 'top_failed':
                original['failed'] = True
            if change == 'top_failure_ids':
                original['failure_ids'] = ['invented::failure']
        return original
    with pytest.raises(ValueError, match='full closure identity differs|exact environment differs|top-level counts/failure IDs'):
        contract.validate_cpu(receipt, review, 'runtime', candidate, evidence, tampered, read_bytes)


