def genuine_runtime9_report_fixture():
    """Copied original selected fields, full39/full490; no report rewrite."""
    candidate, proofs = original_runtime8_literal_pass_fixture()
    original = json.loads(_ORIGINAL_RUNTIME9_REPORT_FIXTURE_JSON)
    metadata = json.loads(_FROZEN_SUCCESSOR_V5_FIXTURE_INPUTS_JSON)
    manifest = metadata['runtime9_manifest']['document']
    candidate.update(runtime_version=9, helpers=str(contract.ROOT / 'tools/fresh200-calibration-v9'))
    candidate['runtime_files'] = [dict(path=str(Path(candidate['helpers']) / row['relative_path']),
        bytes=row['bytes'], sha256=row['sha256']) for row in original['document']['frozen_inputs']['runtime']['records']]
    candidate['proofs']['runtime_manifest'] = metadata['runtime9_manifest']['record']
    candidate['proofs']['source_manifest'].update(bytes=original['document']['frozen_inputs']['source_snapshot']['bytes'])
    proofs.update(runtime_manifest=manifest, runtime_review=original['document'])
    return candidate, proofs


def test_genuine_runtime9_original_independence_and_relative39_are_consumed():
    candidate, proofs = genuine_runtime9_report_fixture()
    assert 'completed_source_CPU_report_used_as_runtime_acceptance' not in proofs['runtime_review']['independence']
    assert 'file_receipts' not in proofs['runtime_review']['frozen_inputs']['runtime']
    contract.validate_static_reviews(candidate, proofs)


@pytest.mark.parametrize('change', ['legacy_missing_key', 'borrow9_for10', 'schema_bool', 'version_bool',
    'status_false', 'scope', 'permission', 'blocker', 'missing_runtime', 'tampered_runtime',
    'wrong_local_digest', 'missing_source', 'tampered_source', 'dirty_source', 'inherited_root'])
def test_genuine_runtime9_cannot_hide_missing_bytes_or_inflated_authority(change):
    candidate, proofs = genuine_runtime9_report_fixture(); review = proofs['runtime_review']
    if change == 'legacy_missing_key':
        review['independence'].pop('completed_CPU_and_runtime8_reports_preserved_unchanged')
    elif change == 'borrow9_for10': candidate['runtime_version'] = 10
    elif change == 'schema_bool': review['schema'] = True
    elif change == 'version_bool': review['runtime_version'] = True
    elif change == 'status_false': review['status'] = False
    elif change == 'scope': review['scope'] = contract.SCOPE
    elif change == 'permission': review['decision']['formal200_authorized'] = True
    elif change == 'blocker': review['blocking_findings'] = [dict(id='unclosed')]
    elif change == 'missing_runtime': review['frozen_inputs']['runtime']['records'].pop()
    elif change == 'tampered_runtime': review['frozen_inputs']['runtime']['records'][0]['sha256'] = 'f' * 64
    elif change == 'wrong_local_digest': review['frozen_inputs']['runtime']['actual_full_runtime_digest'] = contract.records_digest(candidate['runtime_files'])
    elif change == 'missing_source': review['frozen_inputs']['source_snapshot']['full490_records'].pop()
    elif change == 'tampered_source': review['frozen_inputs']['source_snapshot']['full490_records'][0]['sha256'] = 'f' * 64
    elif change == 'dirty_source': review['frozen_inputs']['source_snapshot']['source_clean_verified'] = False
    else: review['independence']['root_conversation_inherited'] = True
