def test_unexecuted_source9_runtime10_protocol_closes_actual_frozen_relative_inventories():
    candidate, proofs = successor_review_protocol_fixture()
    contract.validate_static_reviews(candidate, proofs)
    assert len(candidate['source_files']) == proofs['source_manifest']['full_tracked_source_file_count']
    assert len(candidate['runtime_files']) == proofs['runtime_manifest']['file_count']
    assert proofs['runtime_review']['approved_cpu_policy']['input_file_records'] == candidate['source_files'] + candidate['runtime_files']
    assert proofs['source_review']['fixture_UNEXECUTED_not_an_original_review'] is True


@pytest.mark.parametrize('kind,change', [('source', 'missing_source'), ('runtime', 'missing_source'),
    ('runtime', 'missing_runtime'), ('runtime', 'tampered_runtime'), ('runtime', 'absolute_digest'),
    ('source', 'dirty'), ('source', 'wrong_commit'), ('source', 'wrong_scope'), ('runtime', 'wrong_scope'),
    ('runtime', 'borrow9'), ('runtime', 'schema_bool'), ('source', 'permission'), ('runtime', 'permission'),
    ('runtime', 'inherited_context'), ('source', 'missing_test'), ('runtime', 'missing_test'),
    ('runtime', 'input_omission'), ('runtime', 'undeclared_filter'), ('source', 'plugin')])
def test_successor_exact_protocol_rejects_legacy_or_partial_authority(kind, change):
    candidate, proofs = successor_review_protocol_fixture(); report = proofs[kind + '_review']
    if change == 'missing_source': report['frozen_inputs']['source_snapshot']['full_tracked_source_files'].pop()
    elif change == 'missing_runtime': report['frozen_inputs']['runtime']['records'].pop()
    elif change == 'tampered_runtime': report['frozen_inputs']['runtime']['records'][0]['sha256'] = 'f' * 64
    elif change == 'absolute_digest': report['frozen_inputs']['runtime']['actual_full_runtime_digest'] = contract.records_digest(candidate['runtime_files'])
    elif change == 'dirty': report['frozen_inputs']['source_snapshot']['source_clean_verified'] = False
    elif change == 'wrong_commit': report['frozen_inputs']['source_snapshot']['actual_commit'] = 'f' * 40
    elif change == 'wrong_scope': report['scope'] = contract.CALIBRATION_SCOPE
    elif change == 'borrow9': report['runtime_version'] = 9
    elif change == 'schema_bool': report['schema'] = True
    elif change == 'permission': report['decision']['formal200_authorized'] = True
    elif change == 'inherited_context': report['independence']['root_conversation_inherited'] = True
    elif change == 'missing_test': report['approved_cpu_policy']['test_files'].pop()
    elif change == 'input_omission': report['approved_cpu_policy']['input_file_records'].pop()
    elif change == 'undeclared_filter': report['approved_cpu_policy']['executed_command'].extend(['-k', 'first'])
    else: report['approved_cpu_policy']['execution_environment']['PYTEST_PLUGINS'] = 'unapproved'
    with pytest.raises(ValueError):
        contract.validate_static_reviews(candidate, proofs)


def successor_raw_cpu_fixture(kind, mutate_collection=None, mutate_execution=None,
                              review_fixture=successor_review_protocol_fixture):
    candidate, proofs = review_fixture(); store, evidence = {}, {}
    def bind(path, raw):
        row = dict(path=path, bytes=len(raw), sha256=hashlib.sha256(raw).hexdigest()); store[path] = raw; evidence[path] = row
        return row
    def bind_json(path, value):
        return bind(path, json.dumps(value, sort_keys=True).encode())
    def read(row): return json.loads(store[row['path']])
    static = proofs[kind + '_review']; policy = static['approved_cpu_policy']
    rows = [(name + '::TestWhole::test_parameter[full::nested]', name[:-3].replace('/', '.') + '.TestWhole',
             'test_parameter[full::nested]', 'passed') for name in policy['test_files']]
    run, originals = synthetic_full_cpu_run(bind, bind_json, 'UNEXECUTED-successor-' + kind, policy,
        policy['execution_scope'], candidate['source_commit'], rows, mutate_collection=mutate_collection,
        mutate_execution=mutate_execution, source_identity=contract.successor_cpu_identity(candidate, kind),
        review_sha=candidate['proofs'][kind + '_review']['sha256'])
    if candidate['source_version'] in (10, 11):
        helper = copy.deepcopy(policy['management_helper'])
        evidence[helper['path']] = helper
        originals.append(helper)
    counts = dict(collected=len(rows), passed=len(rows), failed=0, errors=0, skipped=0)
    receipt = dict(status='PASS', gpu_used=False, actual_execution=True, exit_code=0,
        source_commit=candidate['source_commit'], manifest_sha256=policy['snapshot_sha256'], scope=policy['execution_scope'],
        raw_execution_records=originals, current_run=run, current_source_and_test_files=proofs['source_manifest']['full_tracked_source_files'],
        runtime_files_digest=contract.records_digest(candidate['runtime_files']), fixture_UNEXECUTED=True, **counts)
    receipt_record = bind_json('/proofs/UNEXECUTED-successor-' + kind + '-RECEIPT.json', receipt)
    candidate['proofs'][kind + '_cpu'] = receipt_record
    report = dict(status='PASS', source_commit=candidate['source_commit'], manifest_sha256=policy['snapshot_sha256'],
        cpu_receipt_sha256=receipt_record['sha256'], independent_review=True, complete_required_cpu_coverage_accepted=True,
        approved_current_invocation=copy.deepcopy(policy), scope='FRESH200_SOURCE_CPU_EVIDENCE_ONLY' if kind == 'source' else
            'FRESH200_RUNTIME_CPU_EVIDENCE_ONLY', fixture_UNEXECUTED=True)
    def fixture_read(row):
        if row == candidate['proofs'][kind + '_review']:
            return static
        return read(row)
    return receipt, report, candidate, evidence, fixture_read, lambda row: store[row['path']]


