def controls7_final_review_protocol_fixture():
    assert type(_FROZEN_CONTROLS7_COMPAT_INPUTS_JSON) is str, 'Actual final source11/runtime12 freeze still pending'
    metadata = json.loads(_FROZEN_CONTROLS7_COMPAT_INPUTS_JSON)
    return successor_review_protocol_fixture(metadata=metadata, source_version=11, runtime_version=12)


def test_unexecuted_controls7_final_source11_runtime12_metadata_adapter():
    candidate, proofs = controls7_final_review_protocol_fixture()
    contract.validate_static_reviews(candidate, proofs)
    assert (candidate['source_version'], candidate['runtime_version']) == (11, 12)
    assert proofs['source_review']['approved_cpu_policy']['management_helper'] == contract.SOURCE_RUNTIME_CPU_HELPER
    assert proofs['runtime_review']['approved_cpu_policy']['management_helper'] == contract.SOURCE_RUNTIME_CPU_HELPER
    assert len(candidate['source_files']) == proofs['source_manifest']['full_tracked_source_file_count']
    assert len(candidate['runtime_files']) == proofs['runtime_manifest']['file_count']
    assert proofs['source_review']['fixture_UNEXECUTED_not_an_original_review'] is True


@pytest.mark.parametrize('kind,change', [('source', 'helper3'), ('runtime', 'helper3'),
    ('source', 'source_bool'), ('runtime', 'runtime_bool'), ('source', 'unknown_source'),
    ('runtime', 'unknown_runtime'), ('runtime', 'legacy_pair'), ('source', 'missing_source'),
    ('runtime', 'missing_runtime'), ('source', 'old_scope'), ('runtime', 'old_scope')])
def test_unexecuted_controls7_final_adapter_rejects_borrowed_versions_or_incomplete_inputs(kind, change):
    candidate, proofs = controls7_final_review_protocol_fixture(); report = proofs[kind + '_review']
    if change == 'helper3': report['approved_cpu_policy']['management_helper'] = dict(contract.SOURCE_RUNTIME_CPU_HELPER_V3)
    elif change == 'source_bool': candidate['source_version'] = True
    elif change == 'runtime_bool': report['runtime_version'] = True
    elif change == 'unknown_source': candidate['source_version'] = 12
    elif change == 'unknown_runtime': candidate['runtime_version'] = 13
    elif change == 'legacy_pair': candidate['source_version'] = 10
    elif change == 'missing_source': report['frozen_inputs']['source_snapshot']['full_tracked_source_files'].pop()
    elif change == 'missing_runtime': report['frozen_inputs']['runtime']['records'].pop()
    elif kind == 'source': report['scope'] = 'FRESH200_SOURCE_V10_STATIC_CPU_ONLY'
    else: report['scope'] = 'INDEPENDENT_FROZEN_FRESH200_CONTINUATION_V11_STATIC_PREEXEC_REVIEW_ONLY'
    with pytest.raises(ValueError):
        contract.validate_static_reviews(candidate, proofs)


@pytest.mark.parametrize('kind', ['source', 'runtime'])
def test_unexecuted_controls7_final_raw_CPU_adapter_keeps_full_directory_and_helper4_identity(kind):
    args = successor_raw_cpu_fixture(kind, review_fixture=controls7_final_review_protocol_fixture)
    contract.validate_cpu(args[0], args[1], kind, args[2], args[3], args[4], args[5])
    assert args[3][contract.SOURCE_RUNTIME_CPU_HELPER['path']] == contract.SOURCE_RUNTIME_CPU_HELPER
    assert args[0]['fixture_UNEXECUTED'] is True


@pytest.mark.parametrize('kind,change', [('source', 'helper3'), ('runtime', 'helper3'),
    ('source', 'directory_omission'), ('runtime', 'runtime_directory_omission'),
    ('source', 'count_list'), ('runtime', 'count_list')])
def test_unexecuted_controls7_final_raw_CPU_adapter_rejects_nonexact_original_identity(kind, change):
    def mutate(value):
        if change == 'helper3': value['management_helper'] = dict(contract.SOURCE_RUNTIME_CPU_HELPER_V3)
        elif change == 'directory_omission': value['source_after']['source_directory_inventory']['actual_directory_file_names'].pop()
        elif change == 'runtime_directory_omission': value['source_after']['runtime_directory_inventory']['actual_directory_file_names'].pop()
        else: value['actual_cases'] = list(value['executed_canonical_case_ids'])
    args = successor_raw_cpu_fixture(kind, mutate_execution=mutate, review_fixture=controls7_final_review_protocol_fixture)
    with pytest.raises(ValueError):
        contract.validate_cpu(args[0], args[1], kind, args[2], args[3], args[4], args[5])
